import type { VercelRequest, VercelResponse } from '@vercel/node';

let cachedApp: any = null;
let initPromise: Promise<any> | null = null;

async function getAppInstance() {
  if (cachedApp) return cachedApp;
  if (initPromise) return initPromise;

  initPromise = (async () => {
    let createApp: any = null;
    try {
      // Dynamically load the bundled server artifact generated by esbuild
      // @ts-ignore
      const serverBundle = await import('../dist/server.cjs');
      createApp = serverBundle.createApp || serverBundle.default?.createApp || serverBundle.default;
    } catch {
      // Fallback for development, testing, or unbundled serverless environments
      // @ts-ignore
      const serverSource: any = await import('../server.ts');
      createApp = serverSource.createApp || serverSource.default?.createApp || serverSource.default;
    }

    if (!createApp) {
      throw new Error('createApp function not found in dist/server.cjs bundle or server.ts');
    }
    const app = typeof createApp === 'function' ? await createApp() : createApp;
    cachedApp = app;
    return app;
  })();

  return initPromise;
}

export default async function handler(req: VercelRequest, res: VercelResponse) {
  try {
    const app = await getAppInstance();
    return app(req, res);
  } catch (err: any) {
    res.statusCode = 500;
    res.setHeader('Content-Type', 'application/json');
    res.end(JSON.stringify({ error: 'Server initialization failed', detail: err?.message || String(err) }));
  }
}

